  sg_e11_w: { en: `Two units before Fajr, four before Dhuhr and two after it, two after Maghrib, and two after Isha. They make up for shortcomings in the obligatory prayers.`, ms: ``, tur: ``, urd: ``, ben: ``, fas: ``, zh: ``, yue: ``, ja: ``, ru: ``, es: ``, ko: ``, ta: ``, si: `` },
