  sg_e12_w: { en: `Men are strongly encouraged to pray the five prayers in the mosque; at home, praying together with family brings the same reward of congregation.`, ms: ``, tur: ``, urd: ``, ben: ``, fas: ``, zh: ``, yue: ``, ja: ``, ru: ``, es: ``, ko: ``, ta: ``, si: `` },
